/**
 * A card's monster type ignores its rank: Undead Warrior (1) and
 * Undead Warrior (3) are the same type.
 */
const distinctMonsterTypes = (army: Card[]): Set<string> =>
  new Set(army.map((card) => card.monster));

/**
 * "Sphinx — 1 point. 2 per type beyond three, else 1."
 *
 * The flat 1 point, plus either 2 for every type beyond the third or a
 * single point when there are no more than three.
 */
const scoreOneSphinx = (typeCount: number): number =>
  1 +
  (typeCount > MAX_TYPES_FOR_BASE_SCORE
    ? (typeCount - MAX_TYPES_FOR_BASE_SCORE) * SCORE_PER_TYPE_BEYOND
    : 1);

export const scoreArmy = (army: Card[]): number =>
  army.reduce((score, card, index) => {
    if (card.monster !== SPHINX) return score;

    const otherCards = army.filter((_, other) => other !== index);
    return score + scoreOneSphinx(distinctMonsterTypes(otherCards).size);
  }, 0);

