/**
 * How many cards carry each monster type. A card's type ignores its rank:
 * Undead Warrior (1) and Undead Warrior (3) are the same type.
 */
const tallyMonsterTypes = (army: Card[]): Map<string, number> =>
  army.reduce(
    (tally, card) => tally.set(card.monster, (tally.get(card.monster) ?? 0) + 1),
    new Map<string, number>(),
  );

/**
 * A Sphinx counts the types around it, not its own — but a second Sphinx
 * keeps "sphinx" on the board. So the card's type still counts unless this
 * card is the only one carrying it.
 */
const countTypesAroundOneCard = (
  tally: Map<string, number>,
  card: Card,
): number => tally.size - (tally.get(card.monster) === 1 ? 1 : 0);

/**
 * "Sphinx — 1 point. 2 per type beyond three, else 1."
 *
 * The flat 1 point, plus either 2 for every type beyond the third or a
 * single point when there are no more than three.
 */
const scoreOneSphinx = (otherTypeCount: number): number =>
  1 +
  (otherTypeCount > MAX_TYPES_FOR_BASE_SCORE
    ? (otherTypeCount - MAX_TYPES_FOR_BASE_SCORE) * SCORE_PER_TYPE_BEYOND
    : 1);

export const scoreArmy = (army: Card[]): number => {
  const tally = tallyMonsterTypes(army);

  return army
    .filter((card) => card.monster === SPHINX)
    .reduce(
      (score, sphinx) =>
        score + scoreOneSphinx(countTypesAroundOneCard(tally, sphinx)),
      0,
    );
};
